exercises.solutionCode:
#include <stddef.h>
#define ACCEL_NORM_SCALE 32768.0f

int normalize_accel(const short *raw, int n, float *out)
{
    if (raw == NULL || out == NULL || n <= 0) {
        return -1;
    }

    for (int i = 0; i < n; i++) {
        /* 素材的归一化方式：先转 float 再除以 32768.0f，范围 [-1.0, 1.0) */
        out[i] = (float)raw[i] / ACCEL_NORM_SCALE;
    }
    return 0;
}

int argmax_f32(const float *values, int n)
{
    if (values == NULL || n <= 0) {
        return -1;
    }

    int best = 0;
    for (int i = 1; i < n; i++) {
        if (values[i] > values[best]) {   /* 严格大于 => 并列时保留最小下标 */
            best = i;
        }
    }
    return best;
}
